-- MapBiomas Alerta (alertas de desmatamento validados, camada publica do servidor de mapas do MapBiomas Alerta) como
-- ESPELHO VERSIONADO: vetorial.mapbiomas_alerta. Idempotente. So ASCII de proposito.
-- Rodar como postgres (o etl so tem DML):
--   Get-Content mapbiomas\alerta\sql\01_tabela.sql | docker exec -i dw-postgis psql -U postgres -d data_warehouse -v ON_ERROR_STOP=1
-- Indices secundarios e chaves so depois da primeira carga (02_indices_chaves.sql): carregar com eles e bem mais lento.
--
-- Regras (as mesmas do SICAR e do PRODES): a tabela espelha o que o servidor publica hoje; cada alerta (alert_code) tem versoes
-- (vigente_desde/vigente_ate); alerta que o servidor deixa de publicar tem a versao FECHADA (nada e apagado na coleta); alerta que
-- some e volta IDENTICO tem a versao reaberta. Colunas com os nomes da fonte (alert_code, area_ha, ...), texto sempre `text`.
-- ATENCAO: a camada traz alertas CANCELADOS (status_name = 'cancelled') junto com os publicados; filtre na analise.

CREATE TABLE IF NOT EXISTS vetorial.mapbiomas_alerta (
    id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    alert_code        integer     NOT NULL,                 -- fonte: alert_code (chave estavel do alerta)
    area_ha           numeric,                              -- fonte: area_ha (hectares, 4 casas)
    sources           text,                                 -- fonte: sources (sistemas de deteccao, separados por virgula)
    biomes            text,                                 -- fonte: biomes
    states            text,                                 -- fonte: states (nome por extenso; pode listar mais de um)
    cities            text,                                 -- fonte: cities (pode listar mais de um)
    detected_at       date,                                 -- fonte: detected_at (data da deteccao)
    year_detected_at  smallint,                             -- fonte: year_detected_at
    published_at      date,                                 -- fonte: published_at (data da publicacao do alerta validado)
    image_after_at    date,                                 -- fonte: image_after_at
    image_before_at   date,                                 -- fonte: image_before_at
    deforestation_driver text,                              -- fonte: deforestation_driver (agriculture, garimpo, urban_expansion, others...)
    status_name       text,                                 -- fonte: status_name (published, cancelled)
    lat               double precision,                     -- fonte: lat (ponto representativo)
    lng               double precision,                     -- fonte: lng
    crossed_special_territories text,                       -- fonte: crossed_special_territories (Amazonia Legal, MATOPIBA, Semiarido...)
    crossed_rural_properties_total integer,                 -- fonte: crossed_rural_properties_total (imoveis rurais cruzados)
    geom              geometry(MultiPolygon, 4674),         -- fonte: geom (SIRGAS 2000). NULL quando geom_anomala
    geom_anomala      boolean     NOT NULL DEFAULT false,   -- true = caixa fora do Brasil ou sem geometria na origem
    geom_origem_texto text,                                 -- EWKT como a fonte entregou, SO quando geom_anomala
    id_fonte          smallint    NOT NULL,
    importado_em      date        NOT NULL DEFAULT current_date,
    vigente_desde     date        NOT NULL DEFAULT current_date,
    vigente_ate       date,
    coletado_em       timestamptz NOT NULL DEFAULT now(),
    reaberto_em       date                                  -- data em que o alerta voltou identico e a versao foi reaberta
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_mapbiomas_alerta_vigente ON vetorial.mapbiomas_alerta (alert_code) WHERE vigente_ate IS NULL;

COMMENT ON TABLE vetorial.mapbiomas_alerta IS
    'MapBiomas Alerta: poligonos de alertas de desmatamento (camada dashboard-alert-shapefile do servidor de mapas do MapBiomas Alerta), espelho versionado: vigente = vigente_ate IS NULL. Inclui alertas cancelados (status_name). Ver mapbiomas/alerta/LEIAME_mapbiomas_alerta.md.';
COMMENT ON COLUMN vetorial.mapbiomas_alerta.alert_code IS 'Origem: alert_code. Chave estavel; uma versao vigente por alerta.';
COMMENT ON COLUMN vetorial.mapbiomas_alerta.status_name IS 'Origem: status_name. published = valido; cancelled = cancelado depois (filtre na analise).';
COMMENT ON COLUMN vetorial.mapbiomas_alerta.geom_anomala IS 'true = a fonte entregou o alerta sem geometria ou com a caixa fora do Brasil; o original esta em geom_origem_texto.';

-- Fonte: o MapBiomas Alerta e do MapBiomas (dim.fontes ja tem 'MapBiomas')
