GRANT SELECT, INSERT, UPDATE, DELETE ON vetorial.mapbiomas_alerta TO etl;      -- DELETE: so para a rotina de retencao
GRANT SELECT ON vetorial.mapbiomas_alerta TO leitura, geoserver, analistas;

SELECT 'vetorial.mapbiomas_alerta' AS item, count(*)::text AS valor FROM vetorial.mapbiomas_alerta;
